+        // unlike the C++ QLocale API. Iterating 1..12 would skip January and
+        // measure an empty string for the out-of-range index 12.
+        for (let i = 0; i < 12; i++) {
+            const name = Qt.locale().monthName(i, fmt);
+            const width = timeMetrics.advanceWidth(name);
+            if (width > widestWidth) {
