+
+import QtQuick
+import QtTest
+import "../format.js" as Format
+
+TestCase {
+    name: "DigitalClockFormat"
+
+    function test_replaceUnquotedFormat_data() {
+        return [
+            {
+                tag: "unquoted",
+                format: "hh:mm",
+                expected: "HH:mm"
+            },
+            {
+                tag: "quoted",
+                format: "hh 'hour'",
+                expected: "HH 'hour'"
+            },
+            {
+                tag: "escaped quote",
+                format: "hh 'o''clock'",
+                expected: "HH 'o''clock'"
+            },
+            {
+                tag: "unclosed quote",
+                format: "hh 'hour",
+                expected: "HH 'hour"
+            },
+        ];
+    }
+
+    function test_replaceUnquotedFormat(data) {
+        compare(Format.replaceUnquotedFormat(data.format, /h+/g, match => match.toUpperCase()), data.expected);
+    }
+
+    function test_quoteState() {
+        verify(Format.hasUnclosedQuote("h:mm 'literal"));
+        verify(Format.hasUnclosedQuote("h:mm '"));
+        verify(!Format.hasUnclosedQuote("h:mm 'literal'"));
+        verify(!Format.hasUnclosedQuote("h:mm ''"));
+        compare(Format.replaceUnquotedFormat("h ''m", /m/g, "M"), "h ''M");
+    }
+
+    function test_tokensIgnoreQuotedLiterals() {
+        verify(Format.hasAmPm("h AP"));
+        verify(!Format.hasAmPm("h 'AP'"));
+        verify(Format.hasSeconds("hh:mm:ss"));
+        verify(!Format.hasSeconds("hh:mm 'ss'"));
+        verify(Format.hasTimezone("hh:mm %{timezone}"));
+        verify(Format.hasTimezone("hh:mm ttt"));
+        verify(!Format.hasTimezone("hh:mm 'ttt'"));
+    }
+
+    function test_expandTimezone() {
+        const date = new Date(2000, 0, 1, 13, 5, 6, 789);
+
+        compare(Format.expandTimezone("hh:mm %{timezone}", "Europe/Vienna"), "hh:mm 'Europe/Vienna'");
+        compare(Format.expandTimezone("hh:mm t tt ttt tttt", "UTC+08:00"), "hh:mm 'UTC+08:00' 'UTC+08:00' 'UTC+08:00' 'UTC+08:00'");
+        compare(Format.expandTimezone("hh:mm 't %{timezone}'", "UTC"), "hh:mm 't %{timezone}'");
+        compare(Format.expandTimezone("hh:mm t", "O'Fallon"), "hh:mm 'O''Fallon'");
+        compare(Format.expandTimezone("hh:mm t", ""), "hh:mm ");
+
+        const adjacentTokens = Format.expandTimezone("t%{timezone}", "UTC");
+        compare(adjacentTokens, "'UTCUTC'");
+        compare(Format.renderCustomFormat(date, adjacentTokens, false), "UTCUTC");
+    }
+
+    function test_normalizeCustomFormat() {
+        compare(Format.normalizeCustomFormat("h:mm", false), "h:mm");
+        compare(Format.normalizeCustomFormat("h:mm", true), "h:mm\nAP");
+        compare(Format.normalizeCustomFormat("h:mm 'literal", true), "h:mm 'literal'\nAP");
+        compare(Format.normalizeCustomFormat("h:mm '", true), "h:mm \nAP");
+    }
+
+    function test_quotedLiteral() {
+        compare(Format.quotedLiteral(""), "");
+        compare(Format.quotedLiteral("UTC"), "'UTC'");
+        compare(Format.quotedLiteral("O'Fallon"), "'O''Fallon'");
+    }
+
+    function test_renderCustomFormat() {
+        const date = new Date(2000, 0, 1, 13, 5, 6, 789);
+        compare(Format.renderCustomFormat(date, "'visible'\nAP", true), "visible");
+        compare(Format.renderCustomFormat(date, "'line 1\nline 2'\nAP", true), "line 1\nline 2");
+        compare(Format.renderCustomFormat(date, "'visible'", false), "visible");
+        compare(Format.renderCustomFormat(date, "'visible'", true), "visible");
+    }
+
+    function test_stripsAmPm() {
+        verify(Format.stripsAmPm("h:mm", 0, false));
+        verify(Format.stripsAmPm("h:mm", 1, true));
+        verify(!Format.stripsAmPm("h:mm AP", 0, false));
+        verify(!Format.stripsAmPm("h:mm", 1, false));
+        verify(!Format.stripsAmPm("h:mm", 2, true));
+    }
+}
