@@ -0,0 +1,168 @@
+/*
+    SPDX-FileCopyrightText: 2026 Aaron Tinio <aptinio@gmail.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+.pragma library
+
+/**
+ * Walks a Qt format string, applying transform to each unquoted segment.
+ * Quoted literals ('...') and '' escape sequences are passed through unchanged.
+ */
+function mapUnquotedFormatWithState(format, transform) {
+    let result = "";
+    let segmentStart = 0;
+    let inQuote = false;
+
+    for (let i = 0; i < format.length; ++i) {
+        if (format[i] !== "'") {
+            continue;
+        }
+
+        if (inQuote && i + 1 < format.length && format[i + 1] === "'") {
+            ++i;
+            continue;
+        }
+
+        if (inQuote) {
+            result += format.slice(segmentStart, i + 1);
+            segmentStart = i + 1;
+        } else {
+            result += transform(format.slice(segmentStart, i));
+            segmentStart = i;
+        }
+
+        inQuote = !inQuote;
+    }
+
+    result += inQuote ? format.slice(segmentStart) : transform(format.slice(segmentStart));
+    return {
+        text: result,
+        hasUnclosedQuote: inQuote,
+    };
+}
+
+function mapUnquotedFormat(format, transform) {
+    return mapUnquotedFormatWithState(format, transform).text;
+}
+
+function replaceUnquotedFormat(format, pattern, replacement) {
+    return mapUnquotedFormat(format, part => part.replace(pattern, replacement));
+}
+
+function testUnquotedFormat(format, pattern) {
+    return mapUnquotedFormat(format, part => part.search(pattern) !== -1 ? "\u0000" : "").includes("\u0000");
+}
+
+function hasUnclosedQuote(format) {
+    return mapUnquotedFormatWithState(format, part => part).hasUnclosedQuote;
+}
+
+/**
+ * Wraps text in a Qt quoted literal ('...'), escaping any internal single quotes as ''.
+ * Returns an empty string if text is empty.
+ */
+function quotedLiteral(text) {
+    if (text.length === 0) return "";
+    return `'${text.replace(/'/g, "''")}'`;
+}
+
+/**
+ * Returns true if the format contains an AM/PM token outside quoted literals.
+ * Qt treats a lone unquoted `A`/`a` as the token (the trailing `P`/`p` is an
+ * optional literal), and no other time token uses those letters.
+ */
+function hasAmPm(format) {
+    return testUnquotedFormat(format, /[Aa]/);
+}
+
+/**
+ * Returns true if the format contains a seconds token outside quoted literals.
+ */
+function hasSeconds(format) {
+    return testUnquotedFormat(format, /s+/);
+}
+
+/**
+ * Returns true if the format contains a time-zone token outside quoted
+ * literals — the %{timezone} token or Qt's own t/tt/ttt/tttt. Both are
+ * redirected to the configured zone by expandTimezone, so both count here:
+ * detecting them lets the redundant separate zone label suppress itself.
+ */
+function hasTimezone(format) {
+    return testUnquotedFormat(format, /%\{timezone\}|t{1,4}/);
+}
+
+/**
+ * Returns true if renderCustomFormat must strip a hidden AM/PM indicator: a
+ * 12-hour cycle whose format has no AM/PM token of its own needs one appended
+ * to force 1-12 rendering (see normalizeCustomFormat). The "Time display"
+ * setting owns the cycle decision, not the case the user happened to type.
+ *   use24hConfig: tristate 12h/24h setting — 0 (Qt.Unchecked = 12-hour),
+ *                 1 (Qt.PartiallyChecked = use region default),
+ *                 2 (Qt.Checked = 24-hour).
+ *   localeUses12h: whether the region's short time format has an AM/PM token.
+ */
+function stripsAmPm(format, use24hConfig, localeUses12h) {
+    const uses12hCycle = use24hConfig === 0 || (use24hConfig === 1 && localeUses12h);
+    return uses12hCycle && !hasAmPm(format);
+}
+
+/**
+ * Replaces time-zone tokens (outside quoted literals) with the given text,
+ * wrapped in a Qt quoted literal. Covers both %{timezone} and Qt's own
+ * t/tt/ttt/tttt: Clock.dateTime is a UTC timestamp shifted for JS consumption
+ * (see libclock/clock.cpp) and carries no zone identity, so passing the t
+ * tokens through to Qt would render the system zone rather than the configured
+ * one. Substituting the configured-zone text keeps every zone token truthful.
+ */
+function expandTimezone(format, timezoneText) {
+    return replaceUnquotedFormat(format, /(?:%\{timezone\}|t{1,4})+/g, tokens => {
+        const tokenCount = tokens.match(/%\{timezone\}|t{1,4}/g).length;
+        return quotedLiteral(timezoneText.repeat(tokenCount));
+    });
+}
+
+/**
+ * The format string is authoritative: the tokens the user typed are left as
+ * they are (explicit H stays 24-hour; h with an AM/PM token stays 12-hour).
+ * The only intervention is for the one thing Qt can't express — a bare 12-hour
+ * hour with no visible indicator. When stripAmPm is set (a 12-hour cycle whose
+ * format has no AM/PM token of its own), a hidden "\nAP" is appended to force
+ * Qt to render h as 1-12; renderCustomFormat strips the suffix so nothing shows.
+ * An unmatched quote is closed first so the hidden token remains unquoted; a
+ * lone trailing quote is dropped because closing it would make it visible.
+ */
+function normalizeCustomFormat(format, stripAmPm) {
+    if (!stripAmPm) {
+        return format;
+    }
+
+    if (!hasUnclosedQuote(format)) {
+        return format + "\nAP";
+    }
+
+    // Qt ignores a lone opening quote at the end. Drop it rather than closing
+    // it into a visible apostrophe when the hidden suffix is appended.
+    const closedFormat = format.endsWith("'") ? format.slice(0, -1) : format + "'";
+    return closedFormat + "\nAP";
+}
+
+/**
+ * Formats a datetime using an already-normalized custom format string.
+ * When stripAmPm is true, strips the "\nAP" suffix that normalizeCustomFormat
+ * appended — without AP in the format, Qt treats h as 0-23.
+ */
+function renderCustomFormat(dateTime, format, stripAmPm) {
+    let result = Qt.locale().toString(dateTime, format);
+    if (stripAmPm) {
+        // normalizeCustomFormat only sets stripAmPm after appending "\nAP", so the
+        // separator is always the last newline — even for multi-line custom formats.
+        const separator = result.lastIndexOf("\n");
+        if (separator !== -1) {
+            result = result.substring(0, separator);
+        }
+    }
+    return result;
+}
